/**
 * Copies every **live** issue of a project into a new one, for
 * `ProjectService.cloneProject`: renumbered from 1 in the source issues'
 * number order, reset to `status`, unassigned, with no start or completion
 * time, authored by `authorId`. Labels come along; comments, attachments and
 * links do not. Unlike `copyIssuesToProject`, this walks the whole project —
 * a clone is checked against the full issue count before anything is
 * written, so it must copy that same full count.
 */
export async function cloneLiveIssuesToProject(
  orgId: OrgId,
  fromProjectId: ProjectId,
  toProjectId: ProjectId,
  authorId: UserId,
  status: IssueStatus,
): Promise<number> {
  const db = getDb();
  const rows = db
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, fromProjectId),
        livePredicate(issues.archivedAt, {}),
      ),
    )
    .orderBy(issues.number)
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  const stamp = toIsoTimestamp(new Date());

  rows.forEach((row, index) => {
    const id = newId();
    db.insert(issues)
      .values({
        id,
        orgId,
        projectId: toProjectId,
        number: index + 1,
        title: row.title,
        description: row.description,
        status,
        priority: row.priority,
        authorId,
        assigneeId: null,
        parentId: null,
        estimate: row.estimate,
        dueAt: row.dueAt,
        startedAt: null,
        completedAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    const labelIds = (labels[row.id] ?? []).map((label) => label.id);
    if (labelIds.length > 0) {
      db.insert(issueLabels)
        .values(labelIds.map((labelId) => ({ orgId, issueId: id, labelId })))
        .run();
    }
  });

  return rows.length;
}

/** Cascade behind `ProjectService.archiveProject`; returns the row count. */

