/**
 * Clones a project: a fresh project of the same workspace, named, slugged and
 * keyed by the caller, carrying over the source's description, visibility,
 * colour and lead. Gated like a creation — read on the source, create on the
 * org, the plan's project quota — plus, when `includeIssues` is set, the
 * plan's per-project issue quota against the whole batch of copies, checked
 * before anything is written. Every live issue of the source is copied in
 * number order, renumbered from 1, reset to the workspace's default status,
 * unassigned and authored by the person cloning; archived issues, comments
 * and attachments never come along. Publishes exactly one `project.cloned`
 * event, never `project.created` or `issue.created`.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertNotArchived("Project", source.id, source);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const usedProjects = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", usedProjects)) {
    throw new Error(
      `Plan ${org.plan} allows ${usedProjects} projects; upgrade to add another`,
    );
  }

  const issuesToCopy = input.includeIssues
    ? await issueRepo.countIssues(input.orgId, input.projectId)
    : 0;

  if (
    input.includeIssues &&
    wouldExceedLimit(org.plan, "issuesPerProject", 0, issuesToCopy)
  ) {
    throw new Error(
      `Plan ${org.plan} allows ${getLimit(org.plan, "issuesPerProject")} issues per project; cloning would bring ${issuesToCopy}`,
    );
  }

  const slug = await suggestProjectSlug(input.orgId, input.slug);

  const project = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  const issuesCopied = input.includeIssues
    ? await issueRepo.cloneLiveIssuesToProject(
        input.orgId,
        source.id,
        project.id,
        actor.userId,
        defaultIssueStatus(org.settings.defaultIssueStatus),
      )
    : 0;

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied,
  });

  return project;
}

/**
 * `OrganizationSettings.defaultIssueStatus` is stored as a plain string, so it
 * is re-validated against the enum before it seeds a cloned issue.
 */
function defaultIssueStatus(stored: string): IssueStatus {
  const parsed = issueStatusSchema.safeParse(stored);
  return parsed.success ? parsed.data : "backlog";
}

export async function getProject(

