import { afterAll, beforeAll, describe, expect, it } from "vitest";

import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { subscribe } from "@/lib/event-bus";
import { createTenant, issueInput, useTemporaryDatabase } from "/private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/7ec89613-54e9-48aa-b6b4-6e353feecf72/tests/server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("cloneProject sanity", () => {
  it("copies only live issues, renumbered, reset, under one event", async () => {
    const tenant = await createTenant("clonecheck", "growth");

    const live1 = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Live one", assigneeId: tenant.userIds.admin }),
    );
    const live2 = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Live two" }),
    );
    const archivedOne = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Archived one" }),
    );
    await issueService.archiveIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: archivedOne.id,
    });

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: live1.id,
      status: "in_progress",
    });

    const seen: unknown[] = [];
    const off = subscribe("project.cloned", (p) => seen.push(p));

    const clone = await projectService.cloneProject(tenant.actors.member, {
      orgId: tenant.org.id,
